def evaluate_registered_nurse(registered_nurse):
    """
    Evaluate a registered nurse with a score computed based on several attributes.
    registered_nurse: A registered nurse object, which has the following attributes: empathy, stress_management, medical_knowledge, attention_to_detail, age
    """

    # Assign weights to the attributes
    weights = {
        'empathy': 1, 
        'stress_management': 1, 
        'medical_knowledge': 1,
        'attention_to_detail': 1,
        'age': 1.5  # middle age nurses get higher scores
    }

    # Define a scoring function for all attributes, taking a binary (good/bad) input
    def score(attr):
        if attr == 'good':
            return 1
        else:
            return 0

    # Convert the age category to score
    def age_score(age):
        if age == 'young':
            return weights['age']
        elif age == 'middle':
            return weights['age']
        elif age == 'elder':
            return weights['age'] * 0.5
        else:
            raise ValueError('Invalid age category')

    # Compute the score
    score_value = (
        score(registered_nurse.empathy) * weights['empathy'] +
        score(registered_nurse.stress_management) * weights['stress_management'] +
        score(registered_nurse.medical_knowledge) * weights['medical_knowledge'] +
        score(registered_nurse.attention_to_detail) * weights['attention_to_detail'] +
        age_score(registered_nurse.age)
    )

    return score_value

