def is_palindrome(s):
    return s == s[::-1]

def can_be_palindrome(s):
    count = 0
    for c in set(s):
        if s.count(c) % 2 != 0:
            count += 1
    return count <= 1

def can_be_palindrome_one_deletion(s):
    n = len(s)
    for i in range(n):
        temp = s[:i] + s[i+1:]
        if is_palindrome(temp):
            return True
    return False

