    }

    for attribute, value in scores.items():
        # Scale the attributes scores from 0-10 to 0-5
        scores[attribute] = (value / 10)

    # Scale age scores from young=2, middle=3, elder=4
    age_score = 0
    if detective_and_criminal_investigator.age == "young":
